import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三十三卦 遁 天山遁 乾上艮下","description":"周易 - 第三十三卦 遁 天山遁 乾上艮下","frontmatter":{"title":"第三十三卦 遁 天山遁 乾上艮下","description":"周易 - 第三十三卦 遁 天山遁 乾上艮下"},"headers":[],"relativePath":"zh/classics/zhouyi/034.md","filePath":"zh/classics/zhouyi/034.md"}'),l={name:"zh/classics/zhouyi/034.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="遁" tabindex="-1">遁 <a class="header-anchor" href="#遁" aria-label="Permalink to “遁”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨，小利贞。 彖曰：遁亨，遁而亨也。刚当位而应，与时行也。小利贞，浸而长也。遁之时义大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>天下有山，遁；君子以远小人，不恶而严。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>遁尾，厉，勿用有攸往。象曰：遁尾之厉，不往何灾也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>执之用黄牛之革，莫之胜说。象曰：执用黄牛，固志也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>系遁，有疾厉，畜臣妾吉。象曰：系遁之厉，有疾惫也。畜臣妾吉，不可大事也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>好□君子吉，小人否。象曰：君子好遁，小人否也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>嘉遁，贞吉。象曰：嘉遁贞吉，以正志也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>肥遁，无不利。象曰：肥遁，无不利；无所疑也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
